"""Пример теста в духе проекта.

Правила стиля:
- клиент приложения создаем через TestClient;
- LLM подменяем через app.dependency_overrides, сеть и реальный клиент не нужны;
- фейк детерминированный, запоминает вызовы, чтобы проверять "LLM не вызывался";
- после теста overrides чистим (фикстура), имя теста описывает поведение.
"""
import pytest
from fastapi.testclient import TestClient

from app.llm import get_llm_client
from app.main import app


class FakeLLM:
    def __init__(self) -> None:
        self.calls: list[str] = []

    def review(self, diff: str) -> dict:
        self.calls.append(diff)
        return {"summary": "fake", "comments": []}


@pytest.fixture
def fake_llm():
    fake = FakeLLM()
    app.dependency_overrides[get_llm_client] = lambda: fake
    yield fake
    app.dependency_overrides.clear()


@pytest.fixture
def client():
    return TestClient(app)


def test_review_passes_diff_to_llm_and_returns_its_answer(client, fake_llm):
    response = client.post("/review", json={"diff": "diff --git a/x b/x"})

    assert response.status_code == 200
    assert response.json() == {"summary": "fake", "comments": []}
    assert fake_llm.calls == ["diff --git a/x b/x"]

from fastapi import Depends, FastAPI
from pydantic import BaseModel

from app.llm import LLMClient, get_llm_client

app = FastAPI(title="ai-review-api")


class ReviewRequest(BaseModel):
    diff: str


@app.get("/health")
def health() -> dict:
    return {"status": "ok"}


@app.post("/review")
def review(body: ReviewRequest, llm: LLMClient = Depends(get_llm_client)) -> dict:
    return llm.review(body.diff)

"""Заглушка LLM-клиента: детерминированная, без сети."""


class LLMClient:
    def review(self, diff: str) -> dict:
        files = sum(1 for line in diff.splitlines() if line.startswith("diff --git"))
        return {
            "summary": f"Файлов в diff: {files}",
            "comments": [
                {
                    "file": "unknown",
                    "line": 1,
                    "text": "Заглушка: проверьте изменения вручную.",
                }
            ],
        }


def get_llm_client() -> LLMClient:
    return LLMClient()

